package io.github.astelev.around_planet.space;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class OrbitSurfacesTest {
 private final CelestialSystem system=new CelestialSystem(20000,4e9,1234);
 @Test void eachChartContainsItsOwnGlobeAndDescendantsAtTheCorrectPositions(){long tick=50000;var sun=OrbitSurfaces.scene(system,CelestialSystem.SUN,tick);var earth=OrbitSurfaces.scene(system,CelestialSystem.EARTH,tick);var moon=OrbitSurfaces.scene(system,CelestialSystem.MOON,tick);assertEquals(List.of(CelestialSystem.SUN,CelestialSystem.EARTH,CelestialSystem.MOON),sun.stream().map(OrbitSurfaces.Body::primary).toList());assertEquals(List.of(CelestialSystem.EARTH,CelestialSystem.MOON),earth.stream().map(OrbitSurfaces.Body::primary).toList());assertEquals(1,moon.size());assertEquals(SpaceVector.ZERO,moon.getFirst().center());assertTrue(earth.getLast().center().subtract(system.moon(tick).position()).length()<1e-8);assertTrue(sun.get(1).center().subtract(system.earth(tick).position()).length()<1e-8);assertTrue(sun.get(2).center().subtract(system.origin(CelestialSystem.MOON,tick).position()).length()<1e-8);for(var body:sun){assertEquals(system.radius(body.primary()),body.radius());assertEquals(system.sunlight(body.primary(),SpaceVector.ZERO,tick),body.sunlight());}}
 @Test void offCenterMoonOccludesBackPointsAndUndergroundPointsButNotItsFront(){var spheres=List.of(new OrbitOcclusion.Sphere(new OrbitCamera.Point(0,0,0),4),new OrbitOcclusion.Sphere(new OrbitCamera.Point(8,0,8),2));assertFalse(OrbitOcclusion.visible(new OrbitCamera.Point(8,0,0),spheres));assertFalse(OrbitOcclusion.visible(new OrbitCamera.Point(8,0,8),spheres));assertTrue(OrbitOcclusion.visible(new OrbitCamera.Point(8,0,11),spheres));assertTrue(OrbitOcclusion.visible(new OrbitCamera.Point(11,0,0),spheres));}
 @Test void anOrbitIsSplitAgainstBothPrimaryAndChildSilhouettes(){var spheres=List.of(new OrbitOcclusion.Sphere(new OrbitCamera.Point(0,0,0),4),new OrbitOcclusion.Sphere(new OrbitCamera.Point(8,0,8),2));var a=new OrbitCamera.Point(-12,0,0);var b=new OrbitCamera.Point(12,0,0);var ranges=OrbitOcclusion.ranges(a,b,spheres,false);assertEquals(3,ranges.size());double[][] expected={{0,1.0/3},{2.0/3,.75},{11.0/12,1}};for(int i=0;i<3;i++){assertEquals(expected[i][0],ranges.get(i).from(),1e-10);assertEquals(expected[i][1],ranges.get(i).until(),1e-10);}assertTrue(OrbitOcclusion.ranges(a,b,spheres,true).isEmpty());}
 @Test void analyticClippingMatchesDenseVisibilityAcrossTranslatedSpheres(){var spheres=List.of(new OrbitOcclusion.Sphere(new OrbitCamera.Point(0,0,0),5),new OrbitOcclusion.Sphere(new OrbitCamera.Point(8,2,6),2),new OrbitOcclusion.Sphere(new OrbitCamera.Point(-6,-3,-4),3));var random=new Random(69);for(int line=0;line<100;line++){var a=new OrbitCamera.Point(random.nextDouble()*30-15,random.nextDouble()*20-10,random.nextDouble()*30-15);var b=new OrbitCamera.Point(random.nextDouble()*30-15,random.nextDouble()*20-10,random.nextDouble()*30-15);for(boolean behind:new boolean[]{false,true}){var ranges=OrbitOcclusion.ranges(a,b,spheres,behind);for(int i=0;i<500;i++){double t=(i+.371)/500;var p=new OrbitCamera.Point(a.x()+(b.x()-a.x())*t,a.y()+(b.y()-a.y())*t,a.depth()+(b.depth()-a.depth())*t);boolean expected=(p.depth()<0)==behind&&OrbitOcclusion.visible(p,spheres);boolean shown=ranges.stream().anyMatch(r->t>=r.from()&&t<=r.until());assertEquals(expected,shown,"Incorrect multi-body orbit clipping");}}}}
 @Test void celestialLabelsIgnoreTheirOwnSphereButRespectForegroundBodies(){var camera=new OrbitCamera();var front=camera.fromView(0,0,1);var primary=new OrbitSurfaces.Body(CelestialSystem.EARTH,SpaceVector.ZERO,4,SpaceEnvironment.SUN_DIRECTION);var foreground=new OrbitSurfaces.Body(CelestialSystem.MOON,front.scale(10),2,SpaceEnvironment.SUN_DIRECTION);var background=new OrbitSurfaces.Body(CelestialSystem.MOON,front.scale(-10),2,SpaceEnvironment.SUN_DIRECTION);assertTrue(OrbitSurfaces.markerVisible(foreground.center(),List.of(primary,foreground),camera));assertFalse(OrbitSurfaces.markerVisible(background.center(),List.of(primary,background),camera));}
}
